describe('Mobile Hamburger Menu Navigation', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should open and close the mobile hamburger menu correctly', () => {
    // Verify the hamburger menu icon is visible
    cy.get('[data-testid="hamburger-menu-icon"]').should('be.visible');
    cy.get('[data-testid="hamburger-menu-icon"]').should('have.class', 'hamburger-icon');

    // Click the hamburger menu icon to open the menu
    cy.get('[data-testid="hamburger-menu-icon"]').click();

    // Verify the menu is now visible
    cy.get('[data-testid="mobile-menu"]').should('be.visible');
    cy.get('[data-testid="mobile-menu"]').should('have.class', 'open');

    // Verify menu items are visible
    cy.get('[data-testid="menu-item"]').should('be.visible');
    cy.get('[data-testid="menu-item"]').should('have.text', 'Home');

    // Click the close button to close the menu
    cy.get('[data-testid="menu-close-btn"]').click();

    // Verify the menu is now closed
    cy.get('[data-testid="mobile-menu"]').should('not.exist');
    cy.get('[data-testid="hamburger-menu-icon"]').should('have.class', 'hamburger-icon');

    // Verify the menu icon is still visible
    cy.get('[data-testid="hamburger-menu-icon"]').should('be.visible');
  });

  it('should handle edge case: menu opens and closes multiple times', () => {
    // Open the menu
    cy.get('[data-testid="hamburger-menu-icon"]').click();
    cy.get('[data-testid="mobile-menu"]').should('be.visible');

    // Verify menu is open
    cy.get('[data-testid="mobile-menu"]').should('have.class', 'open');

    // Close the menu
    cy.get('[data-testid="menu-close-btn"]').click();
    cy.get('[data-testid="mobile-menu"]').should('not.exist');

    // Open the menu again
    cy.get('[data-testid="hamburger-menu-icon"]').click();
    cy.get('[data-testid="mobile-menu"]').should('be.visible');

    // Verify menu is open again
    cy.get('[data-testid="mobile-menu"]').should('have.class', 'open');

    // Close the menu
    cy.get('[data-testid="menu-close-btn"]').click();
    cy.get('[data-testid="mobile-menu"]').should('not.exist');

    // Verify the menu icon is still visible
    cy.get('[data-testid="hamburger-menu-icon"]').should('be.visible');
  });
});
